#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Decision {
    Permit,
    Reject,
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum RequestKind {
    Code,
    Media,
    Style,
}

pub struct Rule {
    pub host_suffix: String,
    pub kind: Option<RequestKind>,
    pub decision: Decision,
}

pub struct Policy {
    rules: Vec<Rule>,
}

impl Policy {
    pub fn new(rules: Vec<Rule>) -> Result<Policy, String> {
        if rules.iter().any(|rule| !valid_host(&rule.host_suffix)) {
            return Err("invalid host suffix".to_string());
        }
        Ok(Policy { rules })
    }

    pub fn evaluate(&self, host: &str, kind: RequestKind) -> Decision {
        if !valid_host(host) {
            return Decision::Permit;
        }

        for rule in &self.rules {
            let host_matches = host == rule.host_suffix
                || host
                    .strip_suffix(&rule.host_suffix)
                    .map_or(false, |prefix| prefix.ends_with('.'));
            let kind_matches = rule.kind.is_none() || rule.kind == Some(kind);
            if host_matches && kind_matches {
                return rule.decision;
            }
        }

        Decision::Permit
    }
}

fn valid_host(value: &str) -> bool {
    !value.is_empty()
        && value
            .bytes()
            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'.' || b == b'-')
}
